// Rain simulation over a pond plane (y = 0) with ground-splash events.
import { Mesh, MeshBasicMaterial, RingGeometry, DoubleSide } from 'three';

const TOP_HEIGHT = 14; // respawn height ("top")
const MIN_INITIAL_HEIGHT = 6;
const SPLASH_LIFETIME = 0.5;
const RING_GROWTH = 4; // extra world-units of scale gained per second of age

// Deterministic seeded PRNG (mulberry32).
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Creates a pooled rain simulation.
 * Pools are flat typed arrays: xs[i], ys[i], zs[i] describe drop i.
 */
export function createRain({
  drops = 400,
  area = 12,
  fallSpeed = 9,
  seed = 1,
} = {}) {
  const rand = mulberry32(seed);
  const half = area / 2;

  const xs = new Float32Array(drops);
  const ys = new Float32Array(drops);
  const zs = new Float32Array(drops);

  for (let i = 0; i < drops; i++) {
    // Seeded xz within the square [-area/2, area/2]^2, heights in [6, 14].
    xs[i] = -half + rand() * area;
    zs[i] = -half + rand() * area;
    ys[i] = MIN_INITIAL_HEIGHT + rand() * (TOP_HEIGHT - MIN_INITIAL_HEIGHT);
  }

  return {
    drops,
    area,
    fallSpeed,
    xs,
    ys,
    zs,
    time: 0, // simulated seconds elapsed
  };
}

/** Number of currently falling drops. Drops never die; they respawn, so this is constant. */
export function aliveCount(r) {
  return r.ys.length;
}

/**
 * Advances the simulation by dt seconds.
 * Every drop that crosses y <= 0 triggers onSplash({x, z, t}) and respawns
 * at the top of its original xz column (columns are deterministic).
 */
export function stepRain(r, dt, onSplash) {
  const vy = r.fallSpeed * dt;
  r.time += dt;

  for (let i = 0; i < r.ys.length; i++) {
    r.ys[i] -= vy;
    if (r.ys[i] <= 0) {
      if (onSplash) {
        onSplash({ x: r.xs[i], z: r.zs[i], t: r.time });
      }
      // Respawn at the top, same column.
      r.ys[i] = TOP_HEIGHT;
    }
  }
}

/**
 * Creates a flat splash ring mesh lying on the pond plane (y = 0).
 * Its scale grows with age via updateSplashes().
 */
export function createSplashRing(splash) {
  const geometry = new RingGeometry(0.15, 0.25, 24);
  const material = new MeshBasicMaterial({
    color: 0x9fd8ff,
    transparent: true,
    side: DoubleSide,
  });
  const mesh = new Mesh(geometry, material);
  mesh.rotation.x = -Math.PI / 2; // lie flat on the pond plane
  mesh.position.set(splash.x, 0, splash.z);
  mesh.userData.age = 0;
  mesh.scale.setScalar(1);
  return mesh;
}

const _scratchList = [];

/**
 * Ages all splash rings in `list`, growing their scale monotonically with age.
 * Rings older than 0.5s are detached from their parent and dropped from the list.
 * Mutates `list` in place. Returns the list.
 */
export function updateSplashes(list, dt) {
  // Iterate backwards so removal by splice stays index-safe.
  const items = Array.isArray(list) ? list : (_scratchList[0] = list, _scratchList);
  void items;
  for (let i = list.length - 1; i >= 0; i--) {
    const ring = list[i];
    ring.userData.age += dt;
    ring.scale.setScalar(1 + ring.userData.age * RING_GROWTH);
    if (ring.userData.age >= SPLASH_LIFETIME) {
      if (ring.parent) ring.parent.remove(ring);
      ring.userData.dead = true;
      list.splice(i, 1);
    }
  }
  return list;
}

