import { describe, it, expect } from 'vitest';
import { Scene } from 'three';
import {
  createRain,
  stepRain,
  aliveCount,
  createSplashRing,
  updateSplashes,
} from '../src/rain.js';

describe('rain simulation', () => {
  it('initializes pooled typed arrays with seeded xz and heights in [6, 14]', () => {
    const r = createRain({ drops: 50, area: 12, seed: 7 });
    expect(r.xs).toBeInstanceOf(Float32Array);
    expect(r.ys).toBeInstanceOf(Float32Array);
    expect(r.zs).toBeInstanceOf(Float32Array);
    expect(r.xs.length).toBe(50);
    const half = 12 / 2;
    for (let i = 0; i < 50; i++) {
      expect(r.xs[i]).toBeGreaterThanOrEqual(-half);
      expect(r.xs[i]).toBeLessThanOrEqual(half);
      expect(r.zs[i]).toBeGreaterThanOrEqual(-half);
      expect(r.zs[i]).toBeLessThanOrEqual(half);
      expect(r.ys[i]).toBeGreaterThanOrEqual(6);
      expect(r.ys[i]).toBeLessThanOrEqual(14);
    }
  });

  it('is deterministic for a given seed', () => {
    const a = createRain({ drops: 10, seed: 123 });
    const b = createRain({ drops: 10, seed: 123 });
    expect(Array.from(a.xs)).toEqual(Array.from(b.xs));
    expect(Array.from(a.zs)).toEqual(Array.from(b.zs));
    expect(Array.from(a.ys)).toEqual(Array.from(b.ys));
  });

  it('produces the exact splash count over 5s for a tiny deterministic config', () => {
    // fallSpeed = 10, dt = 0.05 -> 0.5 world units per step, exactly representable.
    // Initial heights [2, 4.5, 7]; respawn height is 14.
    // Crossing steps per drop:
    //   h=2   : 4, then +28 each -> 4, 32, 60, 88        -> 4 splashes
    //   h=4.5 : 9, then +28 each -> 9, 37, 65, 93        -> 4 splashes
    //   h=7   : 14, then +28 -> 14, 42, 70, 98           -> 4 splashes
    // Total within 100 steps (5s): 12.
    const r = createRain({ drops: 3, area: 12, fallSpeed: 10, seed: 1 });
    r.ys[0] = 2;
    r.ys[1] = 4.5;
    r.ys[2] = 7;

    let splashCount = 0;
    for (let s = 0; s < 100; s++) {
      stepRain(r, 0.05, () => splashCount++);
    }
    expect(splashCount).toBe(12);
  });

  it('every splash matches its drop column', () => {
    const r = createRain({ drops: 3, area: 12, fallSpeed: 10, seed: 1 });
    r.ys[0] = 2;
    r.ys[1] = 4.5;
    r.ys[2] = 7;

    const columns = new Set(
      Array.from(r.xs, (_, i) => `${r.xs[i]},${r.zs[i]}`)
    );
    expect(columns.size).toBe(3);

    const splashedColumns = [];
    for (let s = 0; s < 100; s++) {
      stepRain(r, 0.05, ({ x, z }) => splashedColumns.push(`${x},${z}`));
    }
    expect(splashedColumns.length).toBeGreaterThan(0);
    for (const col of splashedColumns) {
      expect(columns.has(col)).toBe(true);
    }
  });

  it('alive drop count stays exactly `drops` throughout the simulation', () => {
    const drops = 25;
    const r = createRain({ drops, area: 12, fallSpeed: 12, seed: 3 });
    expect(aliveCount(r)).toBe(drops);
    for (let s = 0; s < 500; s++) {
      stepRain(r, 0.05, () => {});
      expect(aliveCount(r)).toBe(drops);
      for (let i = 0; i < drops; i++) {
        expect(Number.isFinite(r.ys[i])).toBe(true);
        expect(r.ys[i]).toBeGreaterThan(0);
        expect(r.ys[i]).toBeLessThanOrEqual(14);
      }
    }
  });
});

describe('splash rings', () => {
  it('scale grows monotonically and the ring leaves the scene by 0.6s', () => {
    const scene = new Scene();
    const ring = createSplashRing({ x: 1.5, z: -2.5, t: 0 });
    scene.add(ring);
    expect(scene.children).toContain(ring);
    expect(ring.position.x).toBe(1.5);
    expect(ring.position.z).toBe(-2.5);
    expect(ring.position.y).toBe(0);

    const list = [ring];
    const scales = [ring.scale.x];
    const dt = 0.05;
    // Simulate 0.8s so the 0.5s lifetime is clearly exceeded.
    for (let s = 0; s < 16; s++) {
      updateSplashes(list, dt);
      if (list.length > 0) scales.push(list[0].scale.x);
    }

    // Monotonically increasing while alive.
    for (let i = 1; i < scales.length; i++) {
      expect(scales[i]).toBeGreaterThan(scales[i - 1]);
    }

    // Removed from the scene and from the list well before 0.6s.
    expect(scene.children).not.toContain(ring);
    expect(list.length).toBe(0);
    expect(ring.userData.dead).toBe(true);
    // Age reached lifetime but never far beyond it.
    expect(ring.userData.age).toBeGreaterThanOrEqual(0.5);
    expect(ring.userData.age).toBeLessThan(0.55);
  });

  it('handles many concurrent rings independently', () => {
    const scene = new Scene();
    const list = [];
    for (let i = 0; i < 10; i++) {
      const ring = createSplashRing({ x: i, z: 0, t: 0 });
      scene.add(ring);
      list.push(ring);
    }
    updateSplashes(list, 0.25); // all still alive
    expect(list.length).toBe(10);
    expect(scene.children.length).toBe(10);
    updateSplashes(list, 0.3); // total age 0.55 >= 0.5 -> all gone
    expect(list.length).toBe(0);
    expect(scene.children.length).toBe(0);
  });
});

